Method.Source:
/// <summary>
/// Parm method to get/set the <c>TAMRebateTransactionType</c> for the current process.
/// </summary>
/// <param name = "_rebateTransactionType">Rebate transaction type</param>
/// <returns>Rebate transaction type</returns>
public TAMRebateTransactionType METParmRebateTransactionType(TAMRebateTransactionType _rebateTransactionType = rebateTransactionType)
{
    rebateTransactionType = _rebateTransactionType;

    return rebateTransactionType;
}

/// <summary>
/// Perf improvement by splitting tasks further by vendor rebate type
/// For example instead of creating 1 task for the deal, if we have 5 lines using 3 different rebate types, it will create 3 tasks
/// Make sure this is only done for process > Rebate management
/// </summary>
/// <param name = "_rebateDeal"><c>TAMRebateDeal</c> record</param>
/// <param name = "_rebateTable"><c>TAMRebateTable</c> record</param>
/// <returns>mapKey container</returns>
protected container getMapKeyForSplitingTasks(TAMRebateDeal _rebateDeal, TAMRebateTable _rebateTable)
{
    container mapKey = next getMapKeyForSplitingTasks(_rebateDeal, _rebateTable);

    if (TAMRebateParameters::find().METProcessVendRebateBasedVendRebType
    &&  _rebateDeal.METInvoiceConsolidationByRebateType
    &&  _rebateDeal.RebateReconciliation == TAMRebateReconciliation::Deal
    &&  rebateTransactionType == TAMRebateTransactionType::Rebate)
    {
        mapKey = [TAMRebateReconciliation::Deal, _rebateTable.rebatedeal, _rebateTable.METVendRebateTypeId];
    }

    return mapKey;
}
